   "orig": "事实上，物理观察者不可能真的从 E 穿越到 E′，因为那将涉及一条并非处处类时的世界线（图 30.8）。然而，理论家们常常试图以某种看似微小的方式修改时空，来绕过这一事实。他们的动机来自一种（在我看来误入歧途的）意图：想证明某种科幻式的虫洞旅行——在宇宙之间，或者（把图像稍作修改，如图 30.10）从时空的一个区域到遥远区域——可以由未来的技术实现。这样的方案若能成功，就会开启一种超越相对论正常限制的太空旅行的可能。按真正的《星际迷航》传统，人们设想一种曲率驱动程序，让飞船穿过虫洞抵达遥远区域——那里甚至可能比飞船进入虫洞时更早。听来离奇，可就连广义相对论界的一些一流专家也认真设想过这种时间旅行的可能性。其认真的理由（想必至少有时如此），与其说是时间旅行在现今（或可想象的）物理范围内或许真的可行，不如说是：我们或许能从它物理上本不该可行这一事实中学到些什么。按图 30.8 的空间描述，虫洞在太空旅行者通过之前就捏缩到零尺寸。于是想法是：假如允许负能量密度存在，那么在理论允许的范围内把虫洞撑开足够久、让旅行者穿到另一侧，或许是可以允许的。这类负能量密度在经典理论中通常被禁止，但在适当的量子场论中，特殊情形下或可允许。",
