   "orig": "现在回到量子力学的霍金过程。如 30.4 节所注意到的，太阳质量 1M☉ 黑洞的温度极低（约 10⁻⁷ K）。更大的黑洞温度还要低，与黑洞质量成反比（在给定的 a:m 比值下；见 27.10 节）。没有天体物理证据表明存在质量小于约 1M☉ 的黑洞，因此黑洞温度不被认为具有直接的天体物理意义。尽管如此，这个温度有相当的理论意义，正如霍金在 1974 年戏剧性地指出的。例如，如果宇宙属于永远膨胀的类型（见 27.11 与 28.10 节），那么终有一天，环境温度会降到低于任何给定黑洞的温度。（对一个处在 K = 0 = Λ 宇宙中的 1M☉ 黑洞，这需要约 10¹⁶ 年，约为现今宇宙年龄的 10⁶ 倍。）在那之后，黑洞将开始失去能量：辐射掉的比从背景吸收的多。失去能量就失去质量，半径随之变小，温度因而升高。设想从一个 1M☉ 黑洞出发：它以极慢的速率继续辐射，在约 10⁶⁴ 年里逐渐失去质量，温度先缓慢上升，随后上升得越来越快，直到约 10⁹ K 或 10¹⁰ K（不确定性来自我们对极高能粒子物理的无知）。到那时出现失控的不稳定，一场爆炸随之发生，黑洞中残余的质量—能量几乎瞬时全部转化为辐射！见图 30.14。",
