   "h": "30.8 霍金爆炸（续）",
   "orig": "我本人的看法是：信息丢失显然最有可能。看图 30.14，图像很清楚：坍缩的物质只是落过视界，带着它的全部信息，最终在奇点处被毁灭。视界处不应发生任何有局域物理重要性的事件。物质甚至不知道自己何时越过了视界。应当记住：我们考虑的可能是起初非常大的黑洞，比如被认为栖居于星系中心的那些，质量可达百万太阳质量甚至更多。越过视界时，什么特别的事也没发生：时空曲率与物质密度都不大，只是我们在自己太阳系里见到的那种量级。连视界的位置都不是由局域考虑决定的，因为那个位置取决于后来还有多少物质落入黑洞。若后来有更多物质落入，视界实际上更早就已被越过！见图 30.15。我难以想象：恰在即将越过视界之前，会有什么信号向外界传出坍缩物质所含全部信息的完整细节。其实，光是信号还不够，因为在某种意义上，物质本身就是人们所关心的那个信息。一旦落过视界，物质就被困住，不可避免地要在奇点处被毁灭。",
