   "h": "30.8 霍金爆炸（续）",
   "orig": "斯蒂芬·霍金本人对这些问题的立场是什么？从一开始他就坚决主张丢失，而在我看来，支持这一点的证据如今与霍金当初提出这些想法时一样有力。当然，黑洞蒸发完全是理论概念，大自然对黑洞的遥远未来或许另有安排。但很难看出，若不发生 QFT 或宏观广义相对论（或两者）结构上的剧烈改变，还能有什么替代方案。霍金的立场——至少截至 2003 年——是：幺正性确实应被破坏，但只在我会称之为相当温和的意义上。霍金提议：有黑洞存在时，一个系统的量子态实际上会演化为一个（非纯态的）密度矩阵。这个想法在 29.6 节曾简略提过：如果纠缠量子态的某一部分被真正丢失——这里是其中一部分落入黑洞——而不是仅仅 FAPP 式地丢失，那么把量子实在的本体论立场取为实际由密度矩阵而非（纯）态描写，似乎就是合理的。霍金设想了一种直接施用于密度矩阵的超幺正演化，允许纯态演化为混态。",
