   "h": "30.9 一个更激进的观点（续）",
   "orig": "在这个思想的情形里，随时间推移，自由度在被吸进黑洞奇点时消失。外尔曲率假设约束这些自由度，不许它们在初始（白洞型）奇点中重现；但我的主张是：它们经由 R 过程重现。想法是：黑洞中时间不对称的信息丢失，与 30.3 节所证明的量子力学 R 过程中概率的时间不对称行为之间，存在一种总体平衡。R 过程的非确定性告诉我们：同一输入可以有几个不同输出；这恰好平衡另一件事——有黑洞时，许多不同输入给出同一输出，区分各输入的信息被吸进奇点。回想 30.3 节的假想实验（图 30.1）：对单个给定输入（从 S 发射的光子），我们有两个不同输出（光子到达 D 与到达 C）；而对给定输出（光子到达 D），基本上只有一个输入（在 S 发射的光子）。于是，R 过程造成相空间体积的有效扩张，而时空奇点结构中的不对称造成相空间体积的有效收缩；再见图 30.19。我的主张是：这两种效应平均而言应当彼此抵消。应当明确：这种平衡只是物理过程的一个总体特征。当然，并不是说每一次量子态缩减都必须同时伴随一个黑洞的存在。想法只是：在整个相空间中，这两种效应之间存在平衡。于是，与 R 的未来随机性相平衡的，是黑洞形成的潜在可能性及其吸收信息的能力。",
