   "orig": "不过，我们不应就此放弃。严格说来，要知道下一步怎么做，我们需要合适的新理论；但在我看来，若愿意暂时接受这场冲突、只问作弊涉及的误差有多大，我们就能取得一些真正的进展。让我们采取这样的立场：在某种意义上，只要自由下落的概念在两个时空中相同，大自然就愿意允许这两个时空的局域认同。这算是等效原理的一种反映（17.4 节）。我们所尝试的认同，会让一个空间中测地线的概念与另一个空间中的相合。这通常只能在一点附近的紧邻区域内安排；所以退一步，我们来计算如果真的认同这两个时空会带来多大误差。这类事在完整的广义相对论里很难做，但把光速 c 取为无穷大、同时保留爱因斯坦理论的许多基本哲学，我们可以把其中大部分想法用到这个极限情形。这一情形把我们引向卡坦的牛顿引力表述，如 17.5 节所讨论的。从第 17 章回忆：在牛顿/卡坦引力方案中，时空实际上是一个纤维丛，底空间是允许的不同时间 t 的一维欧几里得空间 E¹，纤维是不同的欧几里得三维空间 E³，每一个指某个给定时间的空间。这样，我们实际上有一个由时间坐标 t 描写的绝对时间。读者或许情有可原地想：既然两个肿块位置的时空现在有相同的（由 t 度量的）时间概念，问题该消失了。但令人遗憾的事实是：知道 t 并不能让我们知道 ∂/∂t。因为算符 ∂/∂t 要求知道其余坐标变量（比如 x、y、z）正被保持固定。这就是 10.3 节考虑的微积分的第二根本混淆（见图 10.7）。参照所涉几何，可以清楚地看到这个问题：知道 t 只告诉我们诸 E³ 截面位于何处，而知道 ∂/∂t 则会告诉我们一个 Killing 矢量场，它定义一族横切这族三维曲面的曲线；见图 30.22。事实上，无法指定薛定谔方程里的 ∂/∂t 这个宽泛问题，即使在更常规的量子引力进路中也被认为很深刻；它与量子宇宙学中所谓的时间问题有关。",
