   "t": "pair",
   "h": "30.11 与爱因斯坦原理的根本冲突（续）",
   "orig": "在当前的语境里，我的野心没那么大，不打算解决所有这些问题。我们只需要：若试图对不同的矢量 k_ψ 与 k_φ 作非法认同，所涉误差的某个估计。做法是：真的把诸 E³ 认同起来，然后取两个空间中引力加速度之差（即自由下落之差，亦即测地线之差）的总误差。设引力加速度分别由三维矢量 G_ψ 与 G_φ 给出。我们这样估计误差：构造差值的平方长度 (G_ψ − G_φ)²，把它在整个 E³ 上积分。这个积分出来的误差，被解释为 ∂/∂t 算符在定义上的绝对不确定性的度量——薛定谔方程需要这个算符，而时间 t 正是选定那张特定 E³ 的标签。这个不确定性经由薛定谔方程，直接导致所考虑叠加态能量的绝对不确定性 E_G。下一步是把 E_G 的表达式换成另一种（等价的）数学形式，我们可以把它解释为：E_G 等于态 |ψ⟩ 与 |φ⟩ 中两个质量分布之差的引力自能。质量分布的引力自能，指把该质量分布从完全散布于无穷远的点质量组装起来所获得的能量。上述的差，可以想成态 |ψ⟩ 中的质量分布取正号，连同态 |φ⟩ 中的质量分布取负号（见图 30.23）。（这之所以不会干脆给出零，是因为能量关心的是每个质量分布的引力场对另一个分布的效应。）用通常的措辞领会这一点有点困难，尤其因为涉及负的质量分布。所幸，在最常考虑的情形——即态 |φ⟩ 只是态 |ψ⟩ 的刚性平移——中，E_G 可以用另一种更直接的方式来解释。我们考虑这样的能量：把肿块的一个实例（原在位置 |ψ⟩）移到位置 |φ⟩，使它离开固定在位置 |ψ⟩ 的另一个实例的引力场，所需花费的能量。在刚性平移的情形，这个能量证明就等于先前的 E_G；其他情形则不一定。",
