   "orig": "然而，让一颗 X 射线光子保持十分之一秒的相干，绝非易事。（不幸的是，需要 X 射线能量，才能给小镜子足够大的动量、产生足够大的位移。）为在这段时间里维持相干，一个建议是把整个实验搬到太空去做：靠两个太空平台上大镜子之间的反射来维持光子相干，两平台或许相隔一个地球直径。光子在这样一段距离上来回一趟约需十分之一秒。从 M 反射的那部分光子波函数被送回 M，在分束器 B 处被反射的那部分则送回 B。计时必须恰到好处，使整个物理过程被精确反转。于是，负责 M 运动的那部分光子波函数恰在 M 回到原位时再次遇到 M，光子收回它交给 M 的动量，使 M 停下来；同时，光子波函数的两个部分被安排在同一时刻于分束器 B 处重新会合。只要这一系列活动过程中没有相位相干性的丢失，且路径长度选得合适，光子的波函数就会合并成单一光束，射回激光器 L。这样，放在备选位置 D 的探测器（光子从分束器 B 出来时本可能到达那里，见图 30.24）将什么也探测不到。这套方案称为 FELIX 提议（自由轨道激光干涉 X 射线实验）。",
